package com.shopsphere.controller; import com.shopsphere.service.WishlistService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/wishlist") public class WishlistController {private final WishlistService s;public WishlistController(WishlistService s){this.s=s;} @GetMapping public List<UUID> all(Authentication a){return s.all(a);} @PostMapping("/{productId}") public void add(Authentication a,@PathVariable UUID productId){s.add(productId,a);} @DeleteMapping("/{productId}") public void remove(Authentication a,@PathVariable UUID productId){s.remove(productId,a);}}